#include <bits/stdc++.h>
using namespace std;

struct Piece {
    int id;
    int k; // number of cells
    vector<pair<int,int>> cells; // original cells
    // All 8 orientations (4 rotations x 2 reflections), normalized
    vector<vector<pair<int,int>>> orientations;
    int minW, minH; // bounding box of best orientation for current target
};

// Normalize: translate so min x=0, min y=0, then sort cells
vector<pair<int,int>> normalize(vector<pair<int,int>> cells) {
    int mx = INT_MAX, my = INT_MAX;
    for (auto& [x,y] : cells) { mx = min(mx, x); my = min(my, y); }
    for (auto& [x,y] : cells) { x -= mx; y -= my; }
    sort(cells.begin(), cells.end());
    return cells;
}

// Get all unique orientations
vector<vector<pair<int,int>>> getOrientations(const vector<pair<int,int>>& cells) {
    set<vector<pair<int,int>>> seen;
    vector<vector<pair<int,int>>> result;
    for (int f = 0; f < 2; f++) {
        for (int r = 0; r < 4; r++) {
            vector<pair<int,int>> cur = cells;
            // Apply flip
            if (f) for (auto& [x,y] : cur) x = -x;
            // Apply rotation r times (90° clockwise each)
            for (int i = 0; i < r; i++) {
                for (auto& [x,y] : cur) {
                    int nx = y, ny = -x;
                    x = nx; y = ny;
                }
            }
            cur = normalize(cur);
            if (seen.insert(cur).second) {
                result.push_back(cur);
            }
        }
    }
    return result;
}

// Get bounding box
pair<int,int> bbox(const vector<pair<int,int>>& cells) {
    int mx = 0, my = 0;
    for (auto& [x,y] : cells) { mx = max(mx, x); my = max(my, y); }
    return {mx+1, my+1};
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<Piece> pieces(n);
    int totalCells = 0;

    for (int i = 0; i < n; i++) {
        pieces[i].id = i;
        cin >> pieces[i].k;
        totalCells += pieces[i].k;
        pieces[i].cells.resize(pieces[i].k);
        for (int j = 0; j < pieces[i].k; j++) {
            cin >> pieces[i].cells[j].first >> pieces[i].cells[j].second;
        }
        pieces[i].orientations = getOrientations(pieces[i].cells);
    }

    // Try multiple target widths and pick the best packing
    // We'll use a bottom-left greedy with skyline approach

    int bestArea = INT_MAX;
    int bestW = -1, bestH = -1;
    vector<tuple<int,int,int,int>> bestPlacement; // x, y, rot, flip

    // Sort pieces by size descending (larger first is usually better for BL)
    vector<int> order(n);
    iota(order.begin(), order.end(), 0);
    sort(order.begin(), order.end(), [&](int a, int b) {
        return pieces[a].k > pieces[b].k;
    });

    // Estimate good widths to try
    int sqrtArea = (int)ceil(sqrt((double)totalCells));

    // Try a range of widths
    vector<int> widthsToTry;
    // Try widths from sqrtArea * 0.7 to sqrtArea * 2.0
    int minW = max(1, (int)(sqrtArea * 0.7));
    int maxW = (int)(sqrtArea * 2.5);
    // For large n, limit the number of widths we try
    int step = max(1, (maxW - minW) / 80);
    for (int w = minW; w <= maxW; w += step) {
        widthsToTry.push_back(w);
    }
    // Also try exact sqrtArea and nearby
    widthsToTry.push_back(sqrtArea);
    widthsToTry.push_back(sqrtArea + 1);
    widthsToTry.push_back(sqrtArea - 1);
    sort(widthsToTry.begin(), widthsToTry.end());
    widthsToTry.erase(unique(widthsToTry.begin(), widthsToTry.end()), widthsToTry.end());

    for (int targetW : widthsToTry) {
        if (targetW < 1) continue;

        // Skyline packing
        // skyline[x] = lowest available y at column x
        vector<int> skyline(targetW, 0);

        vector<tuple<int,int,int,int>> placement(n);
        bool failed = false;

        for (int idx = 0; idx < n && !failed; idx++) {
            int pi = order[idx];
            Piece& p = pieces[pi];

            int bestScore = INT_MAX;
            int bestX = -1, bestY = -1, bestOri = -1;

            // Try all orientations
            for (int oi = 0; oi < (int)p.orientations.size(); oi++) {
                auto& cells = p.orientations[oi];
                auto [w, h] = bbox(cells);

                if (w > targetW) continue;

                // Try all x positions
                for (int x = 0; x <= targetW - w; x++) {
                    // Find the minimum y where this piece can be placed
                    // For each cell, check skyline
                    int minY = 0;
                    for (auto& [cx, cy] : cells) {
                        minY = max(minY, skyline[x + cx] - cy);
                    }

                    // Check all cells are valid
                    int maxCellY = 0;
                    for (auto& [cx, cy] : cells) {
                        maxCellY = max(maxCellY, minY + cy + 1);
                    }

                    // Score: prefer lower placement, then leftward
                    int score = maxCellY * targetW + x;

                    if (score < bestScore) {
                        bestScore = score;
                        bestX = x;
                        bestY = minY;
                        bestOri = oi;
                    }
                }
            }

            if (bestOri == -1) {
                failed = true;
                break;
            }

            // Place the piece
            auto& cells = p.orientations[bestOri];
            for (auto& [cx, cy] : cells) {
                skyline[bestX + cx] = max(skyline[bestX + cx], bestY + cy + 1);
            }

            // Decode orientation: bestOri maps to (flip, rot)
            // We need to figure out which flip/rot corresponds to this orientation
            // Regenerate to find the mapping
            int flip = -1, rot = -1;
            for (int f = 0; f < 2 && flip == -1; f++) {
                for (int r = 0; r < 4 && flip == -1; r++) {
                    vector<pair<int,int>> cur = p.cells;
                    if (f) for (auto& [xx,yy] : cur) xx = -xx;
                    for (int i = 0; i < r; i++) {
                        for (auto& [xx,yy] : cur) {
                            int nx = yy, ny = -xx;
                            xx = nx; yy = ny;
                        }
                    }
                    cur = normalize(cur);
                    if (cur == p.orientations[bestOri]) {
                        flip = f;
                        rot = r;
                    }
                }
            }

            placement[pi] = {bestX, bestY, rot, flip};
        }

        if (failed) continue;

        int H = *max_element(skyline.begin(), skyline.end());
        int area = targetW * H;

        if (area < bestArea || (area == bestArea && H < bestH)) {
            bestArea = area;
            bestW = targetW;
            bestH = H;
            bestPlacement = placement;
        }
    }

    cout << bestW << " " << bestH << "\n";
    for (int i = 0; i < n; i++) {
        auto [x, y, r, f] = bestPlacement[i];
        cout << x << " " << y << " " << r << " " << f << "\n";
    }

    return 0;
}

