    }

    // Sort pieces: largest first, break ties by fewer orientations (more constrained first)
    vector<int> order(n);
    iota(order.begin(), order.end(), 0);
    sort(order.begin(), order.end(), [&](int a, int b) {
        if (pieces[a].k != pieces[b].k) return pieces[a].k > pieces[b].k;
        return pieces[a].oris.size() < pieces[b].oris.size();
    });

    int bestArea = INT_MAX;
    int bestW = -1, bestH = -1;
    vector<tuple<int,int,int,int>> bestPlacement;

    int sqrtArea = max(1, (int)ceil(sqrt((double)totalCells)));

    // Determine widths to try
    vector<int> widthsToTry;
    int lo = max(1, (int)(sqrtArea * 0.8));
    int hi = min(totalCells, (int)(sqrtArea * 2.0));

    // Adaptive step based on n
    int numTrials = (n <= 500) ? 40 : (n <= 2000) ? 25 : 15;
    int step = max(1, (hi - lo) / numTrials);
    for (int w = lo; w <= hi; w += step) widthsToTry.push_back(w);
    for (int d = -2; d <= 2; d++)
        if (sqrtArea + d >= 1) widthsToTry.push_back(sqrtArea + d);
    sort(widthsToTry.begin(), widthsToTry.end());
    widthsToTry.erase(unique(widthsToTry.begin(), widthsToTry.end()), widthsToTry.end());

    for (int targetW : widthsToTry) {
        if (targetW < 1) continue;

        // Use a proper grid for overlap detection
        // But grid can be huge. Use skyline + cell-level check.
        // Skyline approach: skyline[x] = max y+1 used in column x
        // For placement: find lowest y where all cells fit without overlap.
        // Need actual grid to check overlaps for non-rectangular pieces.

        int maxH = (totalCells + targetW - 1) / targetW + 20; // rough upper bound
        maxH = min(maxH, totalCells + 10);
        // Use a bitset per row or a set of occupied cells
        // For speed, use vector<vector<bool>> but only grow as needed

        int curH = 0;
        vector<int> skyline(targetW, 0);
        // occupied: set of (x,y) pairs
        // For speed with large n, use unordered_set or a 2D grid
        // Use a flat hash
        unordered_set<long long> occupied;
        auto key = [](int x, int y) -> long long { return (long long)x * 100001 + y; };

        vector<tuple<int,int,int,int>> placement(n);
        bool failed = false;

        for (int idx = 0; idx < n && !failed; idx++) {
            int pi = order[idx];
            Piece& p = pieces[pi];

            int bestScore = INT_MAX;
            int bx = -1, by = -1, boi = -1;

            for (int oi = 0; oi < (int)p.oris.size(); oi++) {
                auto& cells = p.oris[oi];
                auto [w, h] = bbox(cells);
                if (w > targetW) continue;

                for (int x = 0; x <= targetW - w; x++) {
                    // Start y from skyline-based lower bound
                    int startY = 0;
                    for (auto& [cx, cy] : cells) {
                        startY = max(startY, skyline[x + cx] - cy);
                    }

                    // Try from startY, check actual cells for collision
                    for (int y = startY; y <= startY + 5; y++) {
                        bool ok = true;
                        for (auto& [cx, cy] : cells) {
                            if (occupied.count(key(x+cx, y+cy))) { ok = false; break; }
                        }
                        if (!ok) continue;

                        int maxCellY = 0;
                        for (auto& [cx, cy] : cells)
                            maxCellY = max(maxCellY, y + cy + 1);

                        int score = maxCellY * 100000 + x;
                        if (score < bestScore) {
                            bestScore = score;
                            bx = x; by = y; boi = oi;
                        }
                        break; // first valid y at this x is best for this x
                    }
                }
            }

            if (boi == -1) {
                // Fallback: place at top
                // just stack it
                auto& cells = p.oris[0];
                auto [w, h] = bbox(cells);
                int oi = 0;
                if (w > targetW) {
                    // Try to find an orientation that fits
                    for (int o2 = 0; o2 < (int)p.oris.size(); o2++) {
                        auto [w2, h2] = bbox(p.oris[o2]);
                        if (w2 <= targetW) { oi = o2; w = w2; h = h2; break; }
                    }
                }
                if (w > targetW) { failed = true; break; }
                bx = 0; by = curH; boi = oi;
                // Verify no overlap at curH
                for (auto& [cx, cy] : p.oris[boi]) {
                    if (occupied.count(key(bx+cx, by+cy))) {
                        by = curH + 10; // push further
                        break;
                    }
                }
            }

            auto& cells = p.oris[boi];
            for (auto& [cx, cy] : cells) {
                occupied.insert(key(bx+cx, by+cy));
                skyline[bx+cx] = max(skyline[bx+cx], by+cy+1);
                curH = max(curH, by+cy+1);
            }

            auto [flip, rot] = p.oriFR[boi];
            placement[pi] = {bx, by, rot, flip};
        }

        if (failed) continue;

        int H = curH;
        int area = targetW * H;
        if (area < bestArea || (area == bestArea && (H < bestH))) {
            bestArea = area;
            bestW = targetW;
            bestH = H;
            bestPlacement = placement;
        }
    }

    cout << bestW << " " << bestH << "\n";
    for (int i = 0; i < n; i++) {
