// Simple strip packing: pack pieces in rows of width W
struct Result {
    int W, H;
    vector<tuple<int,int,int,int>> placement;
};

Result stripPack(vector<Piece>& pieces, vector<int>& order, int W) {
    int n = pieces.size();
    Result res;
    res.W = W;
    res.placement.resize(n);

    // Simple next-fit decreasing height shelf packing
    int curX = 0, curY = 0, shelfH = 0;

    for (int idx = 0; idx < n; idx++) {
        int pi = order[idx];
        Piece& p = pieces[pi];

        // Pick orientation that best fits: prefer width <= remaining space, minimize height
        int bestOi = -1;
        int bestW2 = W+1, bestH2 = W+1;

        for (int oi = 0; oi < (int)p.oris.size(); oi++) {
            auto [w, h] = bbox(p.oris[oi]);
            if (w <= W) {
                // Prefer fits in current shelf, then smaller height
                bool fitsShelf = (curX + w <= W);
                if (bestOi == -1 || (fitsShelf && h <= shelfH && h < bestH2) ||
                    (bestW2 > W && fitsShelf) || (h < bestH2 && !fitsShelf && bestW2 > W)) {
                    // Simplify: just pick smallest height that fits width
                    if (h < bestH2 || (h == bestH2 && w < bestW2)) {
                        bestOi = oi;
                        bestW2 = w;
                        bestH2 = h;
                    }
                }
            }
        }

        if (bestOi == -1) {
            // No orientation fits W — this width is impossible
            res.H = INT_MAX;
            return res;
        }

        auto [pw, ph] = bbox(p.oris[bestOi]);

        if (curX + pw > W) {
            // New shelf
            curY += shelfH;
            curX = 0;
            shelfH = 0;
        }

        auto [flip, rot] = p.oriFR[bestOi];
        res.placement[pi] = {curX, curY, rot, flip};
        curX += pw;
        shelfH = max(shelfH, ph);
    }

    res.H = curY + shelfH;
    return res;
}

