    int n = pieces.size();
    Result res;
    res.W = W;
    res.placement.resize(n);
    vector<int> sky(W, 0);

    for (int idx = 0; idx < n; idx++) {
        int pi = order[idx];
        Piece& p = pieces[pi];

        int bestScore = INT_MAX;
        int bx = -1, by = -1, boi = -1;

        for (int oi = 0; oi < (int)p.oris.size(); oi++) {
            auto& cells = p.oris[oi];
            auto [w, h] = bbox(cells);
            if (w > W) continue;

            for (int x = 0; x <= W - w; x++) {
                // For rectangular pieces, skyline is fine
                // For general polyominoes, we need cell-level
                int y = 0;
                for (auto& [cx, cy] : cells) {
                    y = max(y, sky[x + cx] - cy);
                }
                int maxY = 0;
                for (auto& [cx, cy] : cells)
                    maxY = max(maxY, y + cy + 1);

                int score = maxY * 100000 + x;
                if (score < bestScore) {
                    bestScore = score;
                    bx = x; by = y; boi = oi;
                }
            }
        }

        if (boi == -1) { res.H = INT_MAX; return res; }

        for (auto& [cx, cy] : p.oris[boi])
            sky[bx + cx] = max(sky[bx + cx], by + cy + 1);

        auto [flip, rot] = p.oriFR[boi];
        res.placement[pi] = {bx, by, rot, flip};
    }

    res.H = *max_element(sky.begin(), sky.end());
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<Piece> pieces(n);
    int totalCells = 0;

    for (int i = 0; i < n; i++) {
        pieces[i].id = i;
        cin >> pieces[i].k;
        totalCells += pieces[i].k;
        pieces[i].cells.resize(pieces[i].k);
        for (int j = 0; j < pieces[i].k; j++)
            cin >> pieces[i].cells[j].first >> pieces[i].cells[j].second;
        getOrientations(pieces[i]);
    }

    // Sort by decreasing size, then fewer orientations (more constrained first)
    vector<int> order(n);
    iota(order.begin(), order.end(), 0);
    sort(order.begin(), order.end(), [&](int a, int b) {
        if (pieces[a].k != pieces[b].k) return pieces[a].k > pieces[b].k;
        return pieces[a].oris.size() < pieces[b].oris.size();
    });

    int sqrtA = max(1, (int)ceil(sqrt((double)totalCells)));

    int bestArea = INT_MAX;
    int bestW = -1, bestH = -1;
    vector<tuple<int,int,int,int>> bestPlacement;

    // Determine max piece width to set minimum W
    int maxPieceW = 1;
    for (auto& p : pieces) {
        for (auto& ori : p.oris) {
            auto [w,h] = bbox(ori);
            maxPieceW = max(maxPieceW, min(w, h)); // at least one ori has this as width
        }
    }
    // Actually: we need at least one orientation to fit
    int minFeasibleW = 1;
    for (auto& p : pieces) {
        int minW = INT_MAX;
        for (auto& ori : p.oris) {
            auto [w,h] = bbox(ori);
            minW = min(minW, w);
        }
        minFeasibleW = max(minFeasibleW, minW);
    }

    // Try range of widths
    int lo = max(minFeasibleW, (int)(sqrtA * 0.8));
    int hi = min(totalCells, max(sqrtA * 3, minFeasibleW + 1));

    // Adaptive number of trials
    auto tryWidth = [&](int W) {
        if (W < minFeasibleW) return;
        // Try skyline pack
        Result r = skylinePack(pieces, order, W);
        if (r.H < INT_MAX) {
            int area = r.W * r.H;
            if (area < bestArea || (area == bestArea && r.H < bestH)) {
                bestArea = area;
                bestW = r.W;
                bestH = r.H;
                bestPlacement = r.placement;
            }
        }
    };

    int numTrials = min(50, max(10, 500000 / (n + 1)));
    int step = max(1, (hi - lo) / numTrials);

    for (int w = lo; w <= hi; w += step) tryWidth(w);
    for (int d = -5; d <= 5; d++) tryWidth(sqrtA + d);

    // Also try shelf packing for comparison
    auto tryShelf = [&](int W) {
        if (W < minFeasibleW) return;
        Result r = stripPack(pieces, order, W);
        if (r.H < INT_MAX) {
            int area = r.W * r.H;
            if (area < bestArea || (area == bestArea && r.H < bestH)) {
                bestArea = area;
                bestW = r.W;
                bestH = r.H;
                bestPlacement = r.placement;
            }
        }
    };

    for (int w = lo; w <= hi; w += step) tryShelf(w);
    for (int d = -5; d <= 5; d++) tryShelf(sqrtA + d);

    cout << bestW << " " << bestH << "\n";
    for (int i = 0; i < n; i++) {
        auto [x, y, r, f] = bestPlacement[i];
        cout << x << " " << y << " " << r << " " << f << "\n";
    }
    return 0;
}

