36	struct CellHash {
37	    size_t operator()(const pair<long long,long long>& p) const noexcept {
38	        uint64_t x = static_cast<uint64_t>(p.first);
39	        uint64_t y = static_cast<uint64_t>(p.second);
40	        // splitmix-style mixing
41	        x ^= y + 0x9e3779b97f4a7c15ULL + (x<<6) + (x>>2);
42	        x ^= x >> 30; x *= 0xbf58476d1ce4e5b9ULL;
